import React, { useState, useEffect } from 'react';

function WarehouseOrdersProduct() {
    //const { ordernr } = useParams();
    const [products, setProducts] = useState([]);
    const [ warehouseOrderProduct, setarehouseOrderProduct] = useState(null);

    useEffect(() => {
            fetchSupplier(suppliernr);
            console.log("Suppliernr in useEffect:", suppliernr);
            fetchProductsBySupplier(suppliernr);
        }, [suppliernr]);
    
    
        async function fetchOrder(suppliernr) {
            try {
                const response = await fetch(`http://localhost:8080/suppliers/${suppliernr}`);
                if (!response.ok) throw new Error('Failed to fetch supplier');
                const data = await response.json();
                setSupplierInfo(data);
            } catch (error) {
                console.error(error);
            }
        }
    
        async function fetchProductsBySupplier(suppliernr) {
            try {
                const response = await fetch(`http://localhost:8080/product-suppliers/products-by-supplier/${suppliernr}`);
                if (!response.ok) throw new Error('Failed to fetch products');
                const data = await response.json();
                console.log('Products by supplier:', data);
                setProducts(data);
            } catch (error) {
                console.error(error);
            }
        }

    let [search, setSearch] = useState("")
    let [sort, setSort] = useState("ordername")
        
    function onSearchChange(e) {
        setSearch(e.target.value)
    }
    
    function onSortChange(e) {
        setSort(e.target.value)
    }
    
    function getSortedOrderData() {
        return products.filter((item) => {
            return item.productname.toLowerCase().includes(search.toLowerCase())
         }).sort((a, b) => {
            return (a[sort] + "").localeCompare(b[sort] + "")
        })
    }





    return (
        <>
            <div className='listProductsFromSupplier'>
                <h3>Warehouse Order Product</h3>

                <div className="tableFunctions">


                    <div className="tableSeachbar">
                        <i class="bi bi-search"></i>
                        <input class="tableSeachInput" type="text" placeholder="Search" onChange={onSearchChange} value={search}></input>
                    </div>

                    
                    <div className="sortWithAddFunctions">
                        {/* Filter dropdown */}
                        <select className="tableSort" onChange={onSortChange} value={sort}>
                            <option value="productnr">Order nr.</option>
                            <option value="productname">Product</option>
                            <option value="productCategory">Orderdate</option>
                        </select>
                    </div>
                </div>

                <div className="table-container">
                    <table>
                        <thead>
                            <tr>
                                <th>Order nr</th>
                                <th>Product name</th>
                                <th>Product nr</th>
                                <th>Quantity</th>
                                <th>Buyprice</th>
                            </tr>
                        </thead>

                        <tbody>
                            {products.length > 0 &&
                                getSortedOrderData().map((item) => {
                                    return <tr key={item.ordernr}>
                                        <td>{item.ordernr}</td>
                                        <td><a href={ "/inventory/product-details/" + item.productnr}>{item.productname}</a></td>
                                        <td>{item.quantity}</td>
                                        <td>{item.buyprice}</td>
                                    </tr>
                                })
                            }
                        </tbody>
                    </table>
                </div>
            </div>
        </>
  )

}

export default WarehouseOrdersProduct;
